def looped_deep_supervision(loss_fn, outs_per_loop, targets, weights=None):
    # outs_per_loop: 每个循环的输出, len == K
    k = len(outs_per_loop)
    if weights is None:
        weights = [1.0 / k] * k            # 默认等权；原文配比未给出
    total = 0.0
    for w, out in zip(weights, outs_per_loop):
        total = total + w * loss_fn(out, targets)
    return total                            # 循环间深监督：每个循环都拿梯度

def success_rate(results, human=0.834):
    # results: 每个异常审计任务的判定结果, True 表示解决
    sr = sum(1 for r in results if r) / len(results)
    return {"SR": sr, "SR_human": human, "gap": human - sr}


if __name__ == "__main__":
    # 213 个任务：报告区间 6.6% ~ 42.3%，人类 83.4%
    for frac in (0.066, 0.423):
        n_solved = round(213 * frac)
        res = [True] * n_solved + [False] * (213 - n_solved)
        print(frac, success_rate(res))
